        if(source.optBoolean("cancelRequested"))throw new SecurityException("原配置子任务已取消");JSONObject staged=gatewayStagedOwnerRow(child);if(staged==null){if(!source.optString("executorStatus").matches("completed|failed|cancelled"))throw new SecurityException("请先核对并结算原电脑任务；运行中或未知CLI不发行新配置网关");}else requireGatewayStagedParent(child,staged,identity.taskId(),identity.runId(),identity.epoch(),false);
