        return new JSONObject().put("taskId",child).put("runId",source.getString("runId")).put("epoch",source.getInt("coordinatorEpoch")).put("parentTaskId",identity.taskId()).put("parentRunId",identity.runId()).put("parentEpoch",identity.epoch()).put("sourceDigest",capabilityFingerprint(new JSONObject().put("source",gatewayConfigurationSourceDigest(source)).put("billing",relation.optString("billingBindingDigest","original_causal_run"))));
