        if(!child.equals(owner.getString("taskId"))||!source.getString("runId").equals(owner.getString("runId"))||source.getInt("coordinatorEpoch")!=owner.getInt("epoch")||!capabilityFingerprint(new JSONObject().put("source",gatewayConfigurationSourceDigest(source)).put("billing",relation.optString("billingBindingDigest","original_causal_run"))).equals(owner.getString("sourceDigest"))||!relation.getString("parentTaskId").equals(owner.getString("parentTaskId"))||!relation.getString("parentRunId").equals(owner.getString("parentRunId")))throw new SecurityException("原配置子任务或父关联已改变");
