    private LocalMcpInvocationRecord localMcpInvocationRecord(String task,String run,String operation,boolean mandatory)throws Exception {
        JSONObject linked=null;JSONArray approvals=required(task).optJSONArray("approvals");for(int i=0;approvals!=null&&i<approvals.length();i++){JSONObject a=approvals.getJSONObject(i);if(operation.equals(a.optString("nativeMcpOperationId"))&&run.equals(a.optString("runId")))linked=a;}
        if(linked==null){if(mandatory)throw new SecurityException("没有此原任务已消费审批的MCP claim");return null;}
        try(Cursor row=db.rawQuery("SELECT arguments FROM operations WHERE task_id=? AND run_id=? AND operation_id=?",new String[]{task,run,operation})){if(!row.moveToFirst())throw new SecurityException("原本机MCP操作不存在");JSONObject args=new JSONObject(row.getString(0)),job=args.optJSONObject(NativeMcpPrivateFields.HOST_KEY);if(job==null||!dev.pocketengine.features.plugins.McpLocalInvocation.FORMAT.equals(job.optString("format")))throw new SecurityException("原已claim的MCP私有引用缺失/损坏；不能猜没有进程");JSONObject authorization=job.getJSONObject("authorization"),scope=job.getJSONObject("scope");
            if(!linked.getString("id").equals(authorization.getString("approvalId"))||!capabilityFingerprint(authorization).equals(job.optString("authorizationDigest"))||!task.equals(scope.optString("taskId"))||!run.equals(scope.optString("runId"))||!operation.equals(scope.optString("operationId")))throw new SecurityException("原私有MCP引用不属于此真实任务/运行/动作");args.remove(NativeMcpPrivateFields.HOST_KEY);if(!authorization.getString("argumentsHash").equals(capabilityFingerprint(args)))throw new SecurityException("原本机MCP RPC参数哈希不同");dev.pocketengine.features.plugins.McpLocalInvocation.requireExact(job.getJSONObject("exact"),scope);return new LocalMcpInvocationRecord(this,task,run,operation,job);
        }
    }
    private java.util.List<LocalMcpInvocationRecord> localMcpInvocationsForOwnerInternal(String task)throws Exception {
        java.util.List<LocalMcpInvocationRecord> result=new java.util.ArrayList<>();try(Cursor rows=db.rawQuery("SELECT task_id,run_id,operation_id FROM operations WHERE arguments LIKE '%\"_nativeMcpJob\"%'"+(task==null?"":" AND task_id=?"),task==null?null:new String[]{task})){while(rows.moveToNext()){if(result.size()>=128)throw new SecurityException("原MCP历史引用超过本次明确读取上限，未静默截断");LocalMcpInvocationRecord row=localMcpInvocationRecord(rows.getString(0),rows.getString(1),rows.getString(2),false);if(row!=null)result.add(row);}}return java.util.List.copyOf(result);
    }
    public synchronized java.util.List<LocalMcpInvocationRecord> localMcpInvocationsForOwner(String task)throws Exception{requirePrivateOwner(required(task));return localMcpInvocationsForOwnerInternal(task);}
