    /** A local failure settles only an untouched prepared claim; a crossed dispatch stays unknown. */
    public synchronized void remoteBackendAdmissionUnconfirmed(String id,String run,String message)throws Exception {
        db.beginTransaction();try{
            JSONObject task=required(id),row=remoteOperation(id,run,"remote_job"),args=row.getJSONObject("arguments");
            if(!run.equals(task.optString("runId"))||!args.has("backendSelection")||!row.getString("state").matches("remote_job_prepared|remote_job_sending|remote_job_unknown")){db.setTransactionSuccessful();return;}
            boolean unsent=row.getString("state").equals("remote_job_prepared");String status=unsent?(task.optBoolean("cancelRequested")?"cancelled":"failed"):"unknown";
            JSONObject receipt=remoteBackendAdmissionReceipt(args,status).put("message",message).put("queryOnly",!unsent);
            if(unsent){
                receipt.put("nativeLocalDispatchProof",new JSONObject().put("scopeHash",capabilityFingerprint(args)).put("originalPreparedClaimNotConsumed",true)).put("notStartedConfirmed",true).put("processStarted",false);
                ContentValues ended=new ContentValues();ended.put("state","remote_job_receipt");ended.put("receipt",sanitize(receipt).toString());
                if(db.update("operations",ended,"task_id=? AND operation_id=? AND tool='remote_job' AND state='remote_job_prepared'",new String[]{id,run})!=1)throw new SecurityException("原首创派发状态已变化");
                task.put("status",status).put("executionStatus",status).put("summary",message).put("evidence",new JSONObject(receipt.toString()).put("executorStatus",status).put("automaticallyVerified",false));write(task);
                ContentValues closedRun=new ContentValues();closedRun.put("status",status);closedRun.put("updated_at",System.currentTimeMillis());closedRun.put("checkpoint",new JSONObject().put("receipt",sanitize(receipt)).toString());db.update("runs",closedRun,"task_id=? AND run_id=?",new String[]{id,run});
            }else updateExternal(id,receipt,false);
            db.setTransactionSuccessful();
        }finally{db.endTransaction();}
    }
    private static JSONObject projectWithoutNativeFields(JSONObject input)throws Exception{JSONObject result=new JSONObject(input.toString());java.util.Iterator<String> keys=input.keys();while(keys.hasNext()){String key=keys.next();if(key.startsWith("_"))result.remove(key);}return result;}
    /** Same account identity survives configuration/credential revision changes. */
    public synchronized void requireSshAccountAvailable(String resource,String ownTask)throws Exception {
        if(!resource.matches("[a-f0-9]{64}"))throw new SecurityException("SSH账号资源身份无效");
        try(Cursor cursor=db.rawQuery("SELECT task_id,document FROM tasks",null)){while(cursor.moveToNext()){
            String id=cursor.getString(0);if(id.equals(ownTask))continue;JSONObject previous=new JSONObject(cursor.getString(1)),refs=previous.optJSONObject("externalRefs"),selection=previous.optJSONObject("sshSelection");
            boolean matches=refs!=null&&"ssh".equals(previous.optString("feature"))&&resource.equals(refs.optString("resourceId"))||selection!=null&&resource.equals(selection.optString("accountResource"));
            if(matches&&(hasUnresolved(id)||"ssh".equals(previous.optString("feature"))&&previous.optString("status").matches("queued|running|stopping|reconciling")))throw new IllegalStateException("该SSH账号仍有原执行或未决效果，请先核对原任务");
        }}
    }
    /** Original native SSH scope/currentness, not authority inferred from a JSON taskId. */
    public synchronized void requireSshNativeRequest(String id,String run,dev.pocketengine.features.ssh.SshNativeRequest request)throws Exception {
        java.util.Objects.requireNonNull(request);JSONObject task=required(id);requirePrivateOwner(task);JSONObject refs=task.optJSONObject("externalRefs"),saved=refs==null?null:refs.optJSONObject("sshNativeRequest"),scope=request.view();
        if(!"ssh".equals(task.optString("feature"))||!run.equals(task.optString("runId"))||!run.equals(task.optString("operationId"))||task.optInt("coordinatorEpoch",-1)!=0||!request.command().equals(task.optString("command"))
                ||saved==null||!request.requestHash().equals(saved.optString("requestHash"))||!scope.optString("profileId").equals(refs.optString("profileId"))||!scope.optString("profileBinding").equals(saved.optString("profileBinding")))throw new SecurityException("原SSH任务、准确请求或连接版本不匹配；不能凭任务编号派发");
        // This very queued external row is normal admission, not an unknown prior operation.
        if(task.optBoolean("cancelRequested")||!task.optString("status").matches("queued|running")||hasUnresolved(id))throw new SecurityException("原SSH任务已停止或有未决效果，迟到调用不能连接或继续传输");
    }
    /** Native preview source pins only original ownership/current execution; it does not prove web-root authorship. */
