        if(task.optBoolean("cancelRequested")||task.optString("status").matches("cancelled|stopping")||hasUnresolved(captured.getString("taskId"))||!current.optString("executorStatus").matches("running|awaiting_approval|completed|failed"))throw new SecurityException("原电脑任务已停止、失联或有未决效果，不新开或保留网页隧道");
