        boolean generic=dev.pocketengine.features.remote.RemoteHarnessSelection.isGenericWorker(binding.optString("worker")),pi="pi".equals(binding.optString("worker"));if(generic||pi){if(binding.opt("readOnly")!=Boolean.FALSE||binding.opt("externalExecutionRiskAcknowledged")!=Boolean.TRUE)throw new SecurityException("外部成员必须明确实际工具风险");if(generic)dev.pocketengine.features.remote.RemoteHarnessSelection.checked(binding.optJSONObject("harnessSelection"),binding.getString("worker"));}if(!codex&&!claude&&!generic&&!pi)throw new SecurityException("团队外部成员必须绑定原协议及明确工具范围");
