        for(String key:new String[]{"memberId","generation","round"})input.put(key,request.get(key));if(request.has("teamContext"))input.put("teamContext",new JSONObject(request.getJSONObject("teamContext").toString()));
        JSONObject old=read(operation);if(old!=null){if(!request.getString("memberId").equals(old.optString("memberId"))||!run.equals(old.optString("teamRunId"))||request.getInt("round")!=old.optInt("round"))throw new SecurityException("原子操作不能转给另一成员或轮次");JSONObject refs=old.optJSONObject("externalRefs");if(refs==null||!binding.optString("profileId").equals(refs.optString("profileId"))||!binding.optString("environmentId").equals(refs.optString("environmentId"))||old.optBoolean("readOnly")!=binding.optBoolean("readOnly")||old.optBoolean("teamReadOnlyTools")!=binding.optBoolean("teamReadOnlyTools")||!old.optString("worker").equals(binding.getString("worker"))||!old.optString("model").equals(binding.optString("model"))||!old.optString("modeId").equals(binding.optString("modeId")))throw new SecurityException("原子操作的电脑身份或配置已变化");}
        if(old!=null&&generic)dev.pocketengine.features.remote.RemoteHarnessSelection.requireSame(old.optJSONObject("harnessSelection"),binding.optJSONObject("harnessSelection"),binding.getString("worker"));
