            if(claude&&(!receipt.optBoolean("protocolVerified")||!receipt.optBoolean("sessionIdentityConfirmed")||!receipt.optBoolean("teamReadOnlyTools"))||codex&&(!receipt.optBoolean("readOnlyConfirmed")||!receipt.optBoolean("externalToolsDisabled")))throw new SecurityException("原session没有实际协议和工具范围确认");
            if(generic)dev.pocketengine.features.remote.RemoteHarnessSelection.requireResume(receipt,binding.optJSONObject("harnessSelection"),binding.getString("worker"));
            if(pi&&(!receipt.optBoolean("protocolVerified")||!dev.pocketengine.features.remote.RemoteHarnessSelection.piScopeConfirmed(receipt)||!receipt.optBoolean("nativeSettled")||receipt.opt("resourcesHeld")!=Boolean.FALSE||receipt.optJSONObject("processCleanupProof")==null||receipt.getJSONObject("processCleanupProof").opt("processGroupStoppedVerified")!=Boolean.TRUE||receipt.optString("sessionId").isEmpty()||receipt.optString("promptRequestId").isEmpty()||!receipt.optString("sessionId").equals(receipt.optString("threadId"))))throw new SecurityException("Pi原无工具会话尚未实际结算");
            if(!binding.getString("worker").equals(prior.optString("worker"))||!binding.optString("model").equals(prior.optString("model"))||!binding.optString("modeId").equals(prior.optString("modeId"))||binding.optBoolean("teamReadOnlyTools")!=prior.optBoolean("teamReadOnlyTools"))throw new SecurityException("续接不能改变原Harness与模型/工具范围");
            for(String key:new String[]{"profileId","environmentId","worker"})if(!binding.getString(key).equals(source.optString(key)))throw new SecurityException("续接执行位置已变化");
            for(String key:new String[]{"operationId","threadId","serviceBase"})if(!source.getString(key).equals(receipt.optString(key)))throw new SecurityException("续接锚点不属于原TaskStore真实回执");
            if(!source.getString("jobId").equals(receipt.optString("id")))throw new SecurityException("续接不是原远端job");
