            if(modelApproval!=null)modelApproval.checkCurrent();appendEvent(task,new JSONObject().put("type",preparation==null?"remote_owner_continuation":"remote_owner_gateway_prepared").put("previousRunId",old).put("runId",operation).put("coordinatorEpoch",epoch).put("source",source).put("prompt",prompt.trim()));db.setTransactionSuccessful();return remoteOwnerOperation(id,operation);
