            try(Cursor existing=db.rawQuery("SELECT task_id,arguments FROM operations WHERE operation_id=?",new String[]{operation})){if(existing.moveToFirst()){if(!id.equals(existing.getString(0))||!capabilityFingerprint(scope).equals(capabilityFingerprint(new JSONObject(existing.getString(1)).getJSONObject("scope"))))throw new SecurityException("原项目operation被其它scope占用");db.setTransactionSuccessful();return originalRemoteProjectAction(id,operation);}}
