        if(!scope.getString("profileId").equals(current.getString("profileId"))||!scope.getString("serviceBase").equals(current.getString("serviceBase")))throw new SecurityException("项目操作不是原电脑地址");
        if(!fork&&scope.has("versionSource")){JSONObject version=scope.getJSONObject("versionSource"),verified=originalRemoteProjectHistorySource(task.getString("id"),version.getString("jobOperationId"));if(!capabilityFingerprint(version).equals(capabilityFingerprint(verified)))throw new SecurityException("所选历史项目来源不再属于此原任务/run/操作");for(String key:new String[]{"profileId","serviceBase","environmentId","worker","workspaceIdentity"})if(!current.get(key).equals(version.get(key)))throw new SecurityException("当前执行和历史项目的确切工作区边界不一致");if(!scope.getJSONObject("request").getString("jobOperationId").equals(version.getString("jobOperationId")))throw new SecurityException("恢复目标不是所选原历史job");}

