        if(scope==null||!scope.optString("action").matches("START|FORK")||!id.equals(scope.optString("taskId"))||!operation.equals(scope.optString("operationId"))||scope.getJSONObject("request").optJSONObject("projectHistory")==null||!dev.pocketengine.features.remote.RemoteProjectHistory.PROTOCOL.equals(scope.getJSONObject("request").getJSONObject("projectHistory").optString("protocol"))||receipt==null||!operation.equals(receipt.optString("operationId"))||!receipt.optString("id").matches("[A-Za-z0-9_-]{1,80}"))throw new SecurityException("没有此原任务实际登记的历史项目job；只读来源不能由JSON导入");
