            JSONObject target=required(id);boolean localPrepared=row.getString("state").equals(scope.getString("action").equals("RESTORE")?"prepared":"remote_job_prepared");
            if(localPrepared&&actual.optString("status").matches("unknown|not_found|submitting")&&target.optBoolean("cancelRequested")&&target.getString("runId").equals(row.getString("runId"))){
                // Specific native gate only: every project POST consumes this exact SQL state
                // first. This is cancellation/no-dispatch proof, never authority to retry an unknown.
                JSONObject proof=new JSONObject().put("operationId",operation).put("profileId",scope.getString("profileId")).put("serviceBase",scope.getString("serviceBase")).put("status","cancelled").put("nativeLocalDispatchProof",new JSONObject().put("scopeHash",capabilityFingerprint(scope)).put("originalPreparedClaimNotConsumed",true)).put("notStartedConfirmed",true).put("processStarted",false).put("remoteEffectsVerified",false).put("message","本机原native派发领取未发生；取消先于POST，没有请求远端job或文件替换，不表示撤回已派发动作");
                if(scope.getString("action").equals("RESTORE")){ContentValues value=new ContentValues();value.put("state","receipt");value.put("receipt",proof.toString());db.update("operations",value,"task_id=? AND operation_id=? AND tool='remote_file_restore' AND state='prepared'",new String[]{id,operation});}
                else{JSONObject request=scope.getJSONObject("request");proof.put("environmentId",request.getString("environmentId")).put("worker",request.getString("worker"));updateExternal(id,proof);}
                db.setTransactionSuccessful();return;
            }
            if(!scope.getString("action").equals("RESTORE")){if(!actual.optString("status").matches("unknown|not_found|rejected|submitting")){for(String key:new String[]{"environmentId","worker"})if(!scope.getJSONObject("request").getString(key).equals(actual.optString(key)))throw new SecurityException("新项目/分支回执环境不符");if(scope.getString("action").equals("FORK")&&(actual.optJSONObject("sessionBranchSource")==null||!capabilityFingerprint(scope.getJSONObject("request").getJSONObject("forkSource")).equals(capabilityFingerprint(actual.getJSONObject("sessionBranchSource")))))throw new SecurityException("新分支回执改变原会话来源");}updateExternal(id,actual);}
