                if(!request.getString("expectedVersion").equals(actual.optString("previousVersion"))||!dev.pocketengine.features.remote.RemoteProjectHistory.PROTOCOL.equals(actual.optString("projectHistoryProtocol"))||actual.opt("restoresConversation")!=Boolean.FALSE||actual.opt("atomicWorkspaceTransaction")!=Boolean.FALSE||!scope.getJSONObject("desired").getString("sha256").equals(actual.optString("desiredSha256")))throw new SecurityException("恢复回执扩大授权或缺少实际文件来源");
                if(status.equals("completed")&&(!actual.optBoolean("verified")||!actual.optString("version").equals("sha256:"+scope.getJSONObject("desired").getString("sha256"))||actual.getLong("bytes")!=scope.getJSONObject("desired").getLong("bytes")||!actual.optString("fileVersion").matches("[a-f0-9]{64}")))throw new SecurityException("恢复文件尚未取得实际新版本/hash确认");
