            if(scope.getString("jobOperationId").equals(task.optString("runId"))&&task.optInt("coordinatorEpoch")==scope.optInt("coordinatorEpoch",0)&&!task.optBoolean("cancelRequested")&&!task.optString("status").matches("cancelled|completed|stopping"))updateExternal(id,actual,view.getString("action").equals("START"));
