            try(Cursor row=db.rawQuery("SELECT task_id,tool,arguments FROM operations WHERE operation_id=?",new String[]{operation})){if(row.moveToFirst()){if(!id.equals(row.getString(0))||!row.getString(1).equals("remote_group_return")||!capabilityFingerprint(new JSONObject(row.getString(2)).getJSONObject("scope")).equals(capabilityFingerprint(scope)))throw new SecurityException("原群成果操作已属于不同范围");db.setTransactionSuccessful();return originalGroupRemoteReturn(id,operation);}}
