    private JSONObject teamProjectSelection(JSONObject task)throws Exception {
        JSONObject identity=task.optJSONObject("teamAssignment"),origin=task.optJSONObject("origin");if(identity==null||origin==null||!origin.optString("kind").matches("team_assignment|team_integration"))return null;
        JSONObject team=teamWriteTask(identity.getString("teamRunId")),scope=team.getJSONObject("teamWriteScope");if(scope.optJSONObject("projectSelection")==null)return null;
        JSONObject selected;if(origin.getString("kind").equals("team_integration"))selected=dev.pocketengine.features.teams.TeamProjectWorkspaces.forIntegrator(scope.getJSONObject("projectSelection"));else{selected=identity.optJSONObject("projectSelection");if(selected==null&&scope.getJSONObject("projectSelection").optBoolean("remoteProjectIntegratorOnly"))return null;if(selected==null)throw new SecurityException("原团队完整项目选择未绑定成员");if(identity.has("remoteSelection"))throw new SecurityException("远端作者不能继承手机完整项目作者命令");JSONObject item=currentTeamWorkItem(team,identity),expected=null;JSONArray rows=scope.getJSONArray("assignments");for(int i=0;i<rows.length();i++)if(identity.getString("workItemId").equals(rows.getJSONObject(i).optString("workItemId")))expected=rows.getJSONObject(i).optJSONObject("projectSelection");if(item==null||expected==null||!canonical(selected).equals(canonical(expected)))throw new SecurityException("原项目选择不属于当前workItem/ownerGeneration");}
        return new JSONObject(selected.toString());
    }
