                for(int i=0;i<children.length();i++){JSONObject child=required(children.getJSONObject(i).getString("taskId")),identity=child.getJSONObject("teamResearch");JSONArray versions=identity.optJSONArray("materialScopeHistory");if(versions==null)versions=new JSONArray();if(versions.length()>=32)throw new SecurityException("原child资料续审历史已满，未删除旧票据");versions.put(new JSONObject(old.toString()));identity.put("materialScopeHistory",versions).put("materialScope",new JSONObject(scope.toString()));child.put("teamResearch",identity);write(child);}
