        if(!teamParentExecutionCurrent(owner,scope.getString("parentRunId"),originalRunEpoch(owner.getString("id"),scope.getString("parentRunId")))||parentGrant==null||parentGrant.optLong("expiresAt")<=now||owner.optBoolean("cancelRequested")||owner.optString("status").matches("paused|pausing|interrupted|stopping|cancelled|completed"))throw new SecurityException("原父授权已经暂停、停止或到期");
