                            if(!receipt.optString("status").matches("completed|failed")||!Boolean.TRUE.equals(receipt.opt("accepted"))||!receipt.optString("code").matches("project_process_receipt|project_file_receipt")
                                    ||route==null||backend==null||!backend.optBoolean("receiptReceived")||!receipt.getString("status").equals(backend.optString("status"))||!(backend.opt("exitCode") instanceof Integer||backend.opt("exitCode") instanceof Long)
                                    ||!now.getString("id").equals(route.optString("approvalId"))||!capabilityFingerprint(now.getJSONObject("capability")).equals(route.optString("capabilityFingerprint"))
                                    ||!"native_host_operation".equals(route.optString("authority"))||!id.equals(route.optString("taskId"))||!runId.equals(route.optString("runId"))||epoch!=route.optInt("coordinatorEpoch",-1)
                                    ||!rows.getString(0).equals(route.optString("operationId"))||!rows.getString(0).equals(route.optString("jobId"))||!teamProjectReceiptMatchesContext(task.getJSONObject("teamProject"),id,rows.getString(0),receipt))return false;
