                                if(!canonical(route.opt(key)).equals(canonical(nativeRoute.opt(key))))return false;
                            for(String key:new String[]{"command","planDigest","stepId","intent","projectId","checkoutId","sourceDigest","requestDigest"})if(!canonical(exact.get(key)).equals(canonical(route.opt(key))))return false;
